// spec: .qa/e2e/specs/post-create.md · seed: tests/seed.free.spec.ts · кейс .qa/tests/post-create/PC-02.md
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IPHONE, authFile, form, isPostCreate, openComposer, tap } from './post-helpers';

test.use({ ...IPHONE, storageState: authFile('free') });

test.describe('מסך יצירת פוסט', () => {
  test('Пустой пост и пост из пробелов нельзя опубликовать — кнопка неактивна, POST нет @iphone @prod-safe (#1ff0f4)', async ({ page }) => {
    let posts = 0;
    page.on('request', (r) => { if (isPostCreate(r)) posts++; });
    try {
      await openComposer(page);
      const f = form(page);
      // 1. Пусто → «לפרסם» disabled, тап ничего не отправляет
      await expect(f.publish).toBeDisabled();
      await tap(page, f.publish);
      // 2. Только пробелы и переводы строк
      await f.text.fill('   \n  \n ');
      await expect(f.publish).toBeDisabled();
      await tap(page, f.publish);
      // 3. С текстом — активна, после очистки — снова disabled
      await f.text.fill('x');
      await expect(f.publish).toBeEnabled();
      await f.text.fill('');
      await expect(f.publish).toBeDisabled();
      await expect(page).toHaveURL(/\/post\/new$/);
      expect(posts, 'POST /rest/v1/posts (AC3: пустой пост не публикуется)').toBe(0);
    } finally {
      await saveSession(page, 'free');
    }
  });
});
